import { router } from '@inertiajs/vue3';
import {
    getActiveLanguage,
    i18nVue,
    loadLanguageAsync,
} from 'laravel-vue-i18n';
import type { App } from 'vue';

export type AppLocale = 'fr' | 'en';

/**
 * Both languages are bundled (small files): the first paint is already translated.
 * lang/php_*.json are generated by the Vite plugin from lang/{fr,en}/*.php.
 */
const messages = import.meta.glob<{ default: Record<string, string> }>(
    '../../../lang/*.json',
    { eager: true },
);

function resolve(lang: string): Record<string, string> {
    return messages[`../../../lang/${lang}.json`]?.default ?? {};
}

export function installI18n(app: App, locale: AppLocale): void {
    app.use(i18nVue, { lang: locale, fallbackLang: 'en', resolve });
    document.documentElement.lang = locale;
}

/**
 * Follows the server's choice after each visit (language switch, login of a
 * user who saved another language) and keeps <html lang> in sync.
 */
export function syncLocaleWithServer(): void {
    router.on('success', (event) => {
        const locale = event.detail.page.props.locale as AppLocale | undefined;

        if (locale && locale !== getActiveLanguage()) {
            void loadLanguageAsync(locale);
            document.documentElement.lang = locale;
        }
    });
}

/**
 * BCP 47 tag used for numbers and dates: French or English as written in Cameroon.
 */
export function intlLocale(): string {
    return `${getActiveLanguage()}-CM`;
}
